  "text": "📣國小數學考卷索取 之 「換我當老師」\n\n今天是週三數學日，實現了我一直想做的事情\n🔥🔥「讓學生們當老師批改考卷」 🔥🔥\n每個人會拿到一份「已經寫好」的考卷\n作為「小老師」，在沒有解答的情況下\n他們能否全部改對呢！？\n\n目前有的版本\n📌翰林 3～6年級 、康軒 4年級\n因為是幫我的學生們製作的，其他版本目前還沒有，有重疊到單元的，也可以拿來練習！\n\n檔案和注意事項在留言區！！\n歡迎大家來使用，若孩子寫完後\n也可以分享心得和相關的問題喔！\n\n檔案在這裡！！\n若有領取檔案，可以的話，跟我說聲加油或是謝謝，我會很開心的！🤣\n\nhttps://drive.google.com/drive/folders/1p4I0a2lfbx2YXK2jIk2YOqqX7Juq1Aeh?usp=sharing\n\n⚠️注意事項\n\n📌關於「角度」的計算，若橫式沒有寫「度」沒關係，雖然我會讓學生們寫，但現在大部分學校老師會讓學生不用寫。\n\n📌直式的格式，其實加減乘除的符號上下不應該要有數字，但是礙於我真的修了很多次，已經不想再修了，大家加減寫，這個不能算錯喔！\n\n📌直式乘法乘完後在下面做加法時，進位寫下面沒關係，不用算錯。\n\n如果你很想玩，但是礙於沒辦法影印出來，請再稍等我一下，我會盡快弄好「網路版」的，讓你可以改完之後馬上對答案！！\n\n再給我一些時間，我想先讓自己吃飽，我現在人還在補習班，因為我太想分享這個活動了！！！\n\n如果可以，我應該今天晚上就可以弄出網路版的，想要玩的各位，可以開啟小鈴鐺，我會在這裡丟上連結，也會再額外上傳一篇貼文！",
