  "text": "「我通過了！！！！！！」\n「🍍鳳梨，你一定要那麼恐怖😱嗎？！\n「Yesssssss！！！」\n「真的太緊張了！！！」\n\n今天把握機會的人不少，\n有壓線的，也有90分以上的！\n\n從他們緊張到遮住眼睛的看著我改考卷，\n再到我打分數時，全身發抖的向上天祈禱，\n最後看到分數時，露出中樂透一樣的神情，\n孩子們的快樂就是這麼簡單，\n老師的快樂，其實也是如此簡單。\n\n今天還是有2位沒有達到標準，\n沒關係，分數越來越近了，\n有時候是少一個單位，有時候則是寫太快，\n當然，有時候是看不懂自己的字\n\n最後，我讓他們再練習一份基礎運算題，\n希望下禮拜大家都能夠過關",
