  "text": "我是一個很愛操心的老師。\n\n做安親班這麼久了，\n一路上遇到無數個孩子遇到下列問題\n\n父母離異、家庭關係不融洽、經濟狀況差\n家庭教育差、缺乏自信心、學習低落、特生\n\n這些問題不只是存在著，更是逐年增加。\n\n不管是自掏腰包買課外書，\n還是製作額外活動給孩子們，\n甚至是平常口頭上的分享與傳遞，\n我都想讓他們多學一點、多努力一點，\n一定可以改變的，就算只有一點點也沒關係。\n\n在這個比較心態極強的社會中 ，\n讓他們能夠停下來，看見並肯定自己，\n每個人的起跑點都不一樣，\n不需要去別人的賽道跟別人比，\n老師不是要你們都考得很好，\n而是都可以成為一個「好」人。\n\n附圖是我自己買的升私中的講義，\n我都會放在教室後面的書櫃裡，\n讓早早完成作業、評量的孩子可以自己拿去寫，\n答案我不會撕，他們也懂我的用意，\n願意自律、努力的孩子，我也會加點數。\n\n老師沒辦法陪你一輩子，\n但我希望在我們相聚的這段時間，\n我能夠帶給你一些正面影響，\n這樣就夠了。",
