  "text": "🔥國一數學考卷 索取🔥\n\n這是我去年自己出的考卷\n用意是想讓學生們練習「檢查」\n以及判斷算式的對與錯！！！\n\n檔案在留言區！！！\n\n剛剛翻到的，希望可以把它的價值最大化！\n\nhttps://drive.google.com/drive/folders/1ni9Ab6xDQnwFPtv_XcWXi5sxkktEuDBm",
