  "text": "希望有一天\n我能夠帶著學生站上這個舞台\n\n今年我有學生去報考WMI 入選銅獎🥉\n但是礙於諸多因素 所以沒有參加總決賽\n（我忘記他有沒有被通知能不能了🤣）\n但是就算有，他也不會去🥲\n\n我真的很想要培訓出熱愛數學\n且願意跟我一起玩數學的孩子\n並且希望可以帶他們一起前往更高的境界！\n\n有人說這個學區難做\n有人說我不懂得推銷自己\n也有人說我根本是異想天開\n我也不知道欸，我不想為了做而做\n也不想為了宣傳而犧牲掉學生\n就慢慢的累積，也希望在學生來臨時\n我已經是一位自己認可、夠格的數學老師了！\n\n我始終相信\n適合的學生最後都會透過緣分牽上線。",
