  "text": "🍍鳳梨老師 暑期活動分享🍍\n不論是家長還是老師們 甚至是學生本人\n需要者可以看置頂留言喔！\n\n一篇新聞\n📌有「2」份題目\n🧷 1份有「5」題\n\n注音聯想🧠🗣️\n由開頭注音，想出搭配詞語！\n透過推理與對國字的熟悉度\n判斷同時可符合題目要求的詞語！\n\n今天主題\n1.中聯油脂大豆沙拉油致癌物超標⚠️？\n2.軍公教調薪10%！🪖👷👨‍🏫\n3.中國「民族團結法」上路 🚶\n4.男遇難靠生魚、雨水存活🐟☔️💀\n\n今日的主題有健康教育、生命教育與國際局勢的相關議題，常用的家庭沙拉油檢驗超標⚠️，某些族群被調薪，甚至是在外遇難時的奇蹟生還過程，希望可以帶給孩子們惜物、愛物的觀念以及具備完善的生活常識！\n\n以下是雲端連結\n如果打不開，可以私訊我喔！\n或是留言讓我知道！\n\nhttps://drive.google.com/drive/folders/1Ru4cu3ZlEreReM-Fmxm-O7K_5jWQRC_T?usp\n\n打開來不是注音的話很正常！\n\n只需要下載注音字體即可喔！！\n您可以參考一下的網站\n或是google 注音字體下載\n接著按右鍵點安裝\n就可以打開word 測試看看字體\nhttps://flipedu.parenting.com.tw/article/009835",
