  "text": "國小六年級下學期 南一數學第五單元\n🔥🔥🔥怎樣解題🔥🔥🔥\n✨追趕問題的分析與解法✨\n👉基礎追趕\n👉進階追趕\n👉變化追趕\n\n✨公式的形成✨\n相差距離➗速度差=追上的時間\n\n之後星期二都有一個小小的空檔\n看看能不能多多利用時間跟大家分享\n當然，我也非常願意接受各位的評價與提問\n我會好好聽進去，學習永不停止！",
