  "text": "翰林 國小英文\n三年級下學期 Here we go 2  Unit1&2\n\n痾⋯ 應該還有國小生還沒考完月考的吧？\n因為有家長來訊 問有沒有三年級翰林的\n我就再用了一點時間 生成出來\n有需要的 自行收藏🤣🤣🤣🤣\n我要來去休息了\n\n內容 有任何問題\n或是有任何版權問題\n請立刻通知我 我會馬上下架會修改！",
