  "text": "今天是一年級遇到的小魔王\n——————小短文——————\n\n☝️從打草稿開始\n先選擇一個主要的事情👀\n再慢慢引導 寫出一個完整的句子✍️\n我開頭 學生負責往下接 ！\n\n只是想記錄 第一次在星期四碰到\n通常都是星期五 才會有週記或是短文\n哈哈哈哈哈哈哈哈哈\n\n後續 還有再稍微修改內容\n我只是在中間找一個超小的空檔紀錄下來！",
