  "text": "人生第一個 奧數實體班\n終於在 2026/03/07開班了\n\n一路上 做了許多努力\n🥉帶學生參加比賽\n🏋️免費幫學生培訓\n📹瘋狂拍攝線上課程\n🪪奧數教師培訓\n💪教書的經驗累積\n\n我不是什麼很厲害的老師\n我只是一個靠著教育愛❤️和熱忱🔥\n在努力勇敢追夢的人而已。",
