  "text": "雖然⋯但是⋯\n今天的活動還是想跟大家分享🤣\n\n今天是「找錯字」 ❌\n訓練孩子們對國字的敏感度\n平常寫評量時 發現他們的改錯字不太行\n加上他們的造詞 總是會出現很多同音異字\n所以幫他們訓練訓練 ！🏋️\n\n還是有許多國語好手 把全部找出來！\n圖中的紙張  是還沒批改的 所以答案有錯喔🤣\n\n想一起玩的老師 可以打在留言區裡\n但是記得要「防劇透」喔！\n\n貼心提醒\n前面兩張 和 後面兩張不一樣喔！\n因為前面兩張 想讓大家玩玩看\n後面兩張是為了分享成果🤣🤣🤣",
