  "text": "今日份新聞 ！\n不論是家長還是老師們 甚至是學生本人\n需要者可以看置頂留言喔！\n\n一篇新聞\n📌有「2」張題目\n🧷 1張有「5」題\n\n今天主題\n1.肉身「護身障阿伯過馬路」 👼 👍\n2.搭飛機需要提前3小時到機場嗎？✈️\n3.強毒性尼帕病毒🦠\n4.25歲學霸被丟包 遭4車輾過身亡 🚕 🧑‍🎓\n\n今日的主題多半為生命教育以及時間的重要性，希望可以培養孩子們對於生命的重視，以及學習發揮善心、助人為快樂之本的精神，善的循環，最終會回到自己身上的！\n\n午安！您好！\n以下是新聞閱讀測驗的連結喔！\n再麻煩看看能不能打開\n之後如果我有做新聞檔\n都會放在連結裡\n有空都可以來看看喔！\n\nhttps://drive.google.com/drive/folders/1_OPs8yQicX3Y2P7k0uE77EKY_AktXiY3?usp\n\n另外，檔案打開後應該是沒有注音的，若要有注音，需要現在電腦上下載「注音字體」，可以自行google相關操作喔！",
