  "date": "2026-01-25",
  "text": "順便跟大家分享\n今天下午在準備給學生的其中一個小活動\n✏️「創意寫手」 - 自由創作完成故事\n\n目前有五個不同的主題\n圖中是 「低年級」版本的 字數比較少\n也希望可以在寒假的時候訓練他們\n不然平常 他們連造句都寫不出來🥲\n也算是個既輕鬆 又能夠學習的活動！\n\n之後還會再調整，把空格挖多一點\n但我想先讓他們練習 從少的開始\n讓他們感興趣 再來挖空！\n\n有人會期待學生的作品嗎🤣",
