  "text": "國一數學  三段重點題目分享\n一元一次方程式\n\n1.速率問題\n2.年齡問題\n3.面積問題\n4.連續奇數與偶數\n5.折扣問題\n6.定價、售價、成本\n7.房間人數與分配問題\n\n明天 自己的學生要期末考\n趕快寫了份重點題目筆記整理\n也歡迎有需要的人趕快分享給其他人！\n\n速率圖出處\n臉書：小益的布拉格廣場\n題目出處：2-3間國中段考歷屆試題\n若有任何版權問題 我會立刻刪除貼文",
