  "text": "國一 數學 一元一次方程式\n\n以下本人製作的小遊戲 分享\n有需要的人都可以來玩玩喔！\n也可以幫我看看哪裡可以優化得更好\n已經遠離國中的人 也可以回憶一下喔🤣\n底下歡迎貼出你的成績🤣\n\nhttps://g.co/gemini/share/759d70285892\n一元一次方程式 選擇題\n\nhttps://g.co/gemini/share/af60f29df95a\n一元一次方程式 應用問題",
