  "text": "「WMI 世界數學邀請賽」\n\n今天早上的行程\n陪著2位學生 一起來參賽\n我從去年開始 接觸數學競賽\n雖然現在只能錄線上課程\n讓學生自行在家學習\n但 下學期應該就能夠開實體課了\n\n🔥目標是帶喜歡數學的孩子們\n走進更高的數學殿堂！\n\n去年11月的團體賽\n有2位學生 靠著線上課程\n在奧林匹克數學團體競賽\n得到 銀獎和銅獎 更別說 他們只有準備2個月\n而且只有看線上課程 還能夠得名\n對他們和我 都是莫大的鼓勵！\n（賽前的兩個週六  才有實體加練）",
