  "text": "安親班老師們 ！\n聖誕節快到了 🎄 🎅\n會想要怎麼在安親班度過呢？\n\n身為一個喜歡辦活動的老師\n我正規劃辦交換禮物 🎁\n當天⋯可能還會有其他有趣的活動🤣\n目前是定在12/24 剛好星期三 比較多時間",
